const payload = $('Error Trigger').first().json || {};
const SECRET_KEY = /^(?:authorization|proxy-authorization|client-id|client_id|clientid|api-key|api_key|apikey|token|access[-_]?token|refresh[-_]?token|cookie|set-cookie|credential|credentials|password|secret)$/i;
const SECRET_TEXT = /((?:Client-Id|Api-Key|Authorization)\s*[:=]\s*)(?:Bearer\s+)?[^\s,;}{\]]+/gi;
const BEARER_TEXT = /(Bearer\s+)[A-Za-z0-9._~+\/-]{6,}/gi;
function redact(value, depth = 0, seen = new WeakSet()) {
  if (depth > 10) return '[TRUNCATED]';
  if (typeof value === 'string') return value.replace(SECRET_TEXT, '$1[REDACTED]').replace(BEARER_TEXT, '$1[REDACTED]').slice(0, 2_000);
  if (value == null || typeof value !== 'object') return value;
  if (seen.has(value)) return '[CIRCULAR]';
  seen.add(value);
  if (Array.isArray(value)) return value.slice(0, 50).map((entry) => redact(entry, depth + 1, seen));
  const output = {};
  for (const [key, entry] of Object.entries(value).slice(0, 100)) output[key] = SECRET_KEY.test(key) ? '[REDACTED]' : redact(entry, depth + 1, seen);
  return output;
}
const execution = payload.execution || {};
const workflow = payload.workflow || {};
const error = redact(execution.error || payload.error || {});
const context = redact(payload.context || payload.data || {});
return [{ json: {
  ok: false,
  platform: 'OZON',
  workflowId: String(workflow.id || ''),
  workflowName: String(workflow.name || ''),
  executionId: String(execution.id || ''),
  executionUrl: String(execution.url || ''),
  lastNode: String(execution.lastNodeExecuted || ''),
  jobId: String(context.jobId || context.id || ''),
  taskId: String(context.taskId || ''),
  storeId: String(context.storeId || ''),
  publicationId: String(context.publicationId || ''),
  errorName: String(error.name || 'Error'),
  errorCode: String(error.code || ''),
  errorMessage: String(error.message || error.description || 'Unknown workflow error').slice(0, 2_000),
  safeDetails: redact(error.details || {}),
  occurredAt: new Date().toISOString()
} }];
